#!/usr/bin/env Rscript

# ==========================================================
# Script   : objective64_feature_universe_audit.R
# Purpose  : Retain an exploratory or secondary historical analysis for transparent provenance
# Inputs   : see data/README.md and config/paths.yml
# Outputs  : historical workspace outputs; not generated by run_all.sh
# Paper    : Not a final-results workflow entry point
# Seed     : see config/params.yml
# Runtime  : not benchmarked in the public release
# Last run : see provenance/source_provenance.csv
# Source   : guarded-workspace:objective64_evidence_package_20261020/scripts/build_feature_universe_audit.R
# ==========================================================
# Pre-freeze, outcome-free identifier and technical-eligibility audit only.
options(stringsAsFactors = FALSE)

base_dir <- normalizePath(getwd(), mustWork = TRUE)
# Invoke this script from the rebuild root; do not infer a source path from filenames.
if (!file.exists(file.path(base_dir, "audit"))) stop("Run from objective_BIES_rebuild root.")
root_dir <- normalizePath(file.path(base_dir, ".."), mustWork = TRUE)

w <- readRDS(file.path(root_dir, "results/02_WGCNA/network/wgcna_results.rds"))
x <- readRDS(file.path(root_dir, "results/02_WGCNA/vst_top5000.rds"))
hub <- read.csv(file.path(root_dir, "results/02_WGCNA/hub_genes/hub_genes_all.csv"), check.names = FALSE)

yellow <- w$gene_names[tolower(w$module_colors) == "yellow"]
if (length(yellow) != 539L || anyDuplicated(yellow)) stop("Unexpected historical Yellow membership; stop before protocol freeze.")
if (length(w$gene_names) != length(w$module_colors)) stop("Unaligned WGCNA gene/color vectors.")

kme <- hub$kME[match(yellow, hub$gene)]
if (anyNA(kme)) stop("A historical Yellow gene lacks kME audit data.")

legacy13 <- c("CD79A","CD79B","MS4A1","IGHM","BLK","FCRL5","TNFRSF17","MZB1","JCHAIN","DERL3","IGLL5","IGKC","CD22")
legacy4 <- c("MS4A1","IGHM","BLK","JCHAIN")
present <- yellow %in% rownames(x)
dup_matrix_id <- duplicated(rownames(x)) | duplicated(rownames(x), fromLast = TRUE)
matrix_dup_for_gene <- vapply(yellow, function(g) sum(rownames(x) == g) > 1L, logical(1))
finite_values <- rep(FALSE, length(yellow))
variance <- rep(NA_real_, length(yellow))
finite_values[present] <- vapply(yellow[present], function(g) all(is.finite(x[g, ])), logical(1))
variance[present] <- vapply(yellow[present], function(g) stats::var(as.numeric(x[g, ])), numeric(1))
technical_eligible <- present & !matrix_dup_for_gene & finite_values & is.finite(variance) & variance > 0

out <- data.frame(
  gene = yellow,
  module = "yellow",
  kME = kme,
  present_in_survival_matrix = present,
  finite_values = finite_values,
  variance = variance,
  technical_eligible = technical_eligible,
  primary_universe = technical_eligible,
  legacy_F01_13 = yellow %in% legacy13,
  legacy_BIES_4 = yellow %in% legacy4,
  stringsAsFactors = FALSE
)
write.table(out, file.path(base_dir, "results/OBJECTIVE_FEATURE_UNIVERSE.tsv"), sep = "\t", quote = FALSE, row.names = FALSE, na = "NA")

ig_class <- rep("non_Ig_locus", length(yellow))
for (prefix in c("IGHV", "IGHJ", "IGKV", "IGKJ", "IGLV", "IGLJ")) ig_class[startsWith(yellow, prefix)] <- prefix
ig_detail <- data.frame(gene = yellow, ig_locus_class = ig_class, exact_match = present, technical_eligible = technical_eligible)
write.table(ig_detail[ig_detail$ig_locus_class != "non_Ig_locus", ], file.path(base_dir, "audit/YELLOW_IG_LOCI.tsv"), sep = "\t", quote = FALSE, row.names = FALSE)
write.table(data.frame(gene = yellow[!present]), file.path(base_dir, "audit/YELLOW_UNMATCHED_GENES.tsv"), sep = "\t", quote = FALSE, row.names = FALSE)

make_summary <- function(metric, n, matched = NA_integer_, rate = NA_real_, notes = "") data.frame(metric, n, exact_matches = matched, exact_match_rate = rate, notes)
ig <- ig_class != "non_Ig_locus"
summary <- rbind(
  make_summary("Yellow genes", length(yellow), sum(present), mean(present), "Case-sensitive exact matching; no aliases or remapping."),
  make_summary("Unmatched Yellow genes", sum(!present), NA, NA, "Listed in YELLOW_UNMATCHED_GENES.tsv."),
  make_summary("Duplicate identifiers in Yellow module", sum(duplicated(yellow)), NA, NA, "No duplicate Yellow identifiers."),
  make_summary("Duplicate identifiers in locked VST matrix", sum(duplicated(rownames(x))), NA, NA, "No duplicate locked-matrix identifiers."),
  make_summary("All Ig-locus Yellow genes", sum(ig), sum(present & ig), mean(present[ig]), "Prefixes IGHV, IGHJ, IGKV, IGKJ, IGLV, IGLJ."),
  do.call(rbind, lapply(c("IGHV", "IGHJ", "IGKV", "IGKJ", "IGLV", "IGLJ"), function(z) { idx <- ig_class == z; make_summary(z, sum(idx), sum(present[idx]), mean(present[idx]), "Exact case-sensitive match only.") })),
  make_summary("Removed: duplicate", sum(present & matrix_dup_for_gene), NA, NA, "Primary technical exclusion."),
  make_summary("Removed: non-finite", sum(present & !finite_values), NA, NA, "Primary technical exclusion."),
  make_summary("Removed: zero variance", sum(present & finite_values & variance == 0), NA, NA, "Primary technical exclusion."),
  make_summary("Final objective gene universe", sum(technical_eligible), NA, NA, "All technically eligible Yellow genes; no biological or outcome-based filter.")
)
write.table(summary, file.path(base_dir, "audit/GENE_IDENTIFIER_IG_AUDIT.tsv"), sep = "\t", quote = FALSE, row.names = FALSE)

if (sum(technical_eligible) != 492L) stop("Unexpected objective universe count; stop before protocol freeze.")
cat("Outcome-free feature universe audit complete: ", sum(technical_eligible), " eligible genes.\n", sep = "")
